def set_up_team(apps, schema_editor):
    """The usual groups and roles (when there are none yet), current superusers in Owners, and a staff profile for
    every staff account, staff since they joined."""
    Group = apps.get_model("auth", "Group")
    GroupInfo = apps.get_model("users", "GroupInfo")
    Role = apps.get_model("users", "Role")
    User = apps.get_model("auth", "User")
    Staff = apps.get_model("users", "Staff")
    if not GroupInfo.objects.exists():
        for n, (name, desc, color, owners) in enumerate(GROUPS):
            group, _ = Group.objects.get_or_create(name=name)
            GroupInfo.objects.create(group=group, description=desc, color=color, position=n, owners=owners)
    owners = GroupInfo.objects.filter(owners=True).first()
    for user in User.objects.filter(is_staff=True):
        staff, _ = Staff.objects.get_or_create(user=user)
        staff.since = user.date_joined.date()
        staff.save(update_fields=["since"])
        if user.is_superuser and owners:
            user.groups.add(owners.group)
    if not Role.objects.exists():
        for n, (name, desc, color, icon) in enumerate(ROLES):
            Role.objects.create(name=name, description=desc, color=color, icon=icon, position=n)


